entries[93328] = { ["name"] = "Phiole der Sande", ["text"] = "Wirken in 10 sek.\nReagenzien:\nPyriumbeschichtete Kristallphiole , Sande der Zeit (8), Echtgold (12), Fläschchen der Winde (8), Fläschchen der Titanenstärke (8), Tiefsteinöl (8)\nPhiole der Sande\nReittier\n80\nBenötigt Erfahrenes Reiten\nBenutzen: Lehrt Euch, Euch in einen Drachen zu verwandeln, wodurch Ihr einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\nVerwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier." }
