entries[93433] = { ["name"] = "Bodenangriff", ["text"] = "30 Fokus\nKanalisiert (Wirken in 8 sek.) 30 sek. Abklingzeit\nDer Wurm gräbt sich in die Erde und erschüttert den Boden über ihm. Verursacht im Verlauf von 8 Sek. [( 206 + ((Ranged attack power * 0.40) * 0.288)) * 8] Naturschaden." }
