entries[93435] = { ["name"] = "Brüllen des Mutes", ["text"] = "Sofort 45 sek. Abklingzeit\nDas Tier stößt ein Brüllen des Mutes aus, das die Stärke und Beweglichkeit aller Gruppen- und Schlachtzugsmitglieder im Umkreis von 100 Metern um 549 erhöht. Hält 1 Min. lang an." }
entries[93440] = { ["name"] = "Zwergische Babysöckchen", ["text"] = "Wirken in 3 sek. 5\nZunächst dachtet Ihr, sie wären versteinert. Aber nein, sie sind nur wirklich arg verkrustet.\nZwergische Babysöckchen\nWird beim Aufheben gebunden" }
entries[93441] = { ["name"] = "Halskette mit Anhänger der Elune", ["text"] = "Wirken in 3 sek. 5\nElune ist die oberste Gottheit der Nachtelfen. Sie wird mit dem größeren der beiden Monde in Verbindung gebracht, der Weißen Dame. Obwohl sie eine Göttin des Friedens ist, so ist sie dennoch nicht pazifistisch. Einer ihrer Aspekte ist die Nachtkriegerin, welche die Seelen derer, die sich im Leben als tapfer erwiesen, als Sterne über den Nachthimmel reiten lässt.\nHalskette mit Anhänger der Elune\nWird beim Aufheben gebunden" }
entries[93442] = { ["name"] = "Stück versteinertes Holz", ["text"] = "Wirken in 3 sek. 5\nAuch wenn von dem ursprünglichen Holz nichts mehr vorhanden ist, so ist doch seine Maserung perfekt erhalten. Diese Pflanze war vermutlich ein Exemplar einer Palmen- oder Palmfarnart.\nStück versteinertes Holz\nWird beim Aufheben gebunden" }
entries[93443] = { ["name"] = "Seltsamer pelziger Wurm", ["text"] = "Wirken in 3 sek. 5\nDieses Fossil scheint eine Art fehlendes Verbindungsglied zu sein. Es zeigt sowohl Merkmale von Gliederfüßern als auch Würmern. Sein Körper hat die Gestalt eines Wurms, jedoch insekten- oder krebstierartige Stummelbeine. Anscheinend war die Kreatur auch gänzlich von seidigen Haaren bedeckt.\nSeltsamer pelziger Wurm\nWird beim Aufheben gebunden" }
entries[93444] = { ["name"] = "Feines Besteck der Blutskalpe", ["text"] = "Wirken in 3 sek. 5\nGut, es ist wirklich nur ein großes Messer - aber in einer Kultur wie dem Blutskalpstamm zählt jegliches zum Essen verwendetes Werkzeug als feines Besteck.\nFeines Besteck der Blutskalpe\nWird beim Aufheben gebunden" }
entries[93445] = { ["name"] = "Zurück zu Haleh", ["text"] = "Unbegrenzte Reichweite\nWirken in 5 sek.\nTeleportiert Euch zurück zu Haleh. Eine Aufladung. Funktioniert nur in Winterquell." }
